// icon renders a named icon as an inline SVG. The class lands on the <svg>, so
// callers size and colour it from the stylesheet.
//
// An unknown name renders nothing rather than failing the page: an icon is
// decoration, and a typo in a template should not take the admin down.
func icon(name, class string) template.HTML {
	body, ok := iconPaths[name]
	if !ok {
		return ""
	}
	return template.HTML(fmt.Sprintf(
		`<svg class="%s" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" `+
			`stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" `+
			`aria-hidden="true">%s</svg>`,
		template.HTMLEscapeString(class), body))
}
